package com.bqsqwad.heartbreakhealer.feature.entertainment

internal object StoryLibraryBatch72 {
    val stories = listOf(
        StorySeries(
            id = "the_compass_of_old_maps",
            title = "The Compass of Old Maps",
            tagline = "A lost compass points toward a forgotten public path.",
            parts = listOf(
                StoryPart(1, "The Brass Needle", listOf("Nuru found a brass compass inside an old atlas. Its needle pointed toward the railway quarter instead of north. The lid carried the initials E.O. and a date from forty years earlier.", "Her friend Femi recognised the quarter as a district missing from the newest town maps. They took the compass to their retired geography teacher, Mr Ekanem.", "He identified the initials as Esther Okoro, a local mapmaker whose records had disappeared when the old survey office closed.")),
                StoryPart(2, "The North Room", listOf("Mr Ekanem remembered Esther's field notes and her habit of marking public paths in blue pencil. She had donated materials to the municipal library.", "A note inside the compass case mentioned a cabinet labelled North Room. The librarian found a box of Esther's maps there.", "One transparent sheet showed a blue line leading from the railway quarter toward the riverside clinic.")),
                StoryPart(3, "The Vanished Path", listOf("Residents remembered a footpath between the quarter and the clinic, but construction had changed the area.", "Nuru and Femi walked only on public streets with Mr Ekanem. They compared landmarks with the old map and marked where the path seemed to meet the present road.", "A shopkeeper showed them a photograph of the path before construction. A stone marker in the background carried Esther's initials.")),
                StoryPart(4, "The Stone Marker", listOf("The marker was still visible beside a public walkway, partly hidden by vines. Its inscription named Esther as the surveyor who documented the route.", "A council archive entry showed that the path had once been designated for public access, though its sign had disappeared during repairs.", "The students sent the record to the neighbourhood office and requested an inspection.")),
                StoryPart(5, "A Disagreement", listOf("Some residents wanted the path reopened immediately. Others worried that it might no longer be safe or accessible after years of change.", "Nuru suggested that the council inspect it and consult clinic visitors. Femi feared that waiting would make the discovery forgotten.", "Mr Ekanem reminded them that a good map must show present conditions, not simply preserve the past.")),
                StoryPart(6, "A New Survey", listOf("A council surveyor met the students and explained how public routes were assessed. They noted drainage problems, narrow sections, and a crossing that needed attention.", "The survey found that much of the path remained usable, but one section needed repairs and a safer crossing. The council added the work to its maintenance plan.", "Nuru drew a new map with symbols for confirmed paths, closed sections, and proposed improvements.")),
                StoryPart(7, "Esther's Notebook", listOf("A final archive box contained Esther's notebook. She explained that the compass had been a gift from her first surveying team and that its needle was attracted to a small metal pin she used on working maps.", "The students found the pin in a folded map sleeve. It explained the unusual direction and solved the compass mystery.", "They also found Esther's instruction: 'Never let a neat map hide a difficult truth.'")),
                StoryPart(8, "The Community Map", listOf("The council shared the updated route plan at a community meeting. Clinic visitors described where a crossing was needed, and residents suggested a resting place near the steep section.", "The council agreed to repair the path in stages and publish progress updates. The students' map was displayed beside Esther's original.", "Nuru credited the surveyor, residents, and librarian alongside Esther. No single person had solved the problem alone.")),
                StoryPart(9, "A Path Restored", listOf("Months later, the repaired sections reopened with clear signs and an accessible alternative where the old route remained unsuitable.", "Nuru returned the compass and notebook to the library archive. The brass needle still pointed toward the railway quarter, but the map now explained why.", "Femi asked whether they would keep mapping. Nuru opened a fresh page, ready to listen before drawing.")),
                StoryPart(10, "North, at Last", listOf("Their project became a yearly school activity. New students checked old maps, interviewed residents, and sent corrections to the council when streets changed.", "Nuru wrote a note beside Esther's compass: 'A compass can begin a journey, but listening helps make the route worth taking.'", "The mystery was solved, the footpath was being cared for, and Esther's work had returned to the community it was meant to serve."))
            )
        )
    )
}
